import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel 6353c49:
# packet.RequestNetworkSettings{ClientProtocol: 1001}
PROTOCOL_1001 = bytes.fromhex("000003e9")

# generated by gophertunnel 6353c49:
# packet.RequestNetworkSettings{ClientProtocol: 975}
PROTOCOL_975 = bytes.fromhex("000003cf")

GOLDENS = [
    *[
        pytest.param(
            version.RequestNetworkSettingsPacket(client_network_version=1001),
            PROTOCOL_1001,
            id=f"{version.__name__.rpartition('.')[2]}-client-protocol-1001",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.RequestNetworkSettingsPacket(client_network_version=975),
            PROTOCOL_975,
            id=f"{version.__name__.rpartition('.')[2]}-client-protocol-975",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS)
def test_request_network_settings_is_packet_193(version):
    assert version.PACKETS[193] is version.RequestNetworkSettingsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_network_settings_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_network_settings_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS)
def test_request_network_settings_rejects_a_truncated_version(version):
    with pytest.raises(ValueError, match="at byte"):
        version.RequestNetworkSettingsPacket.from_bytes(PROTOCOL_1001[:3])
